<?php declare(strict_types=1); namespace Annam; $seller=$invoice['seller'];$buyer=$invoice['buyer'];$credit=$invoice['kind']==='credit_note';$taxRegistered=$invoice['kind']==='tax_invoice'||($seller['gst_mode']??'')==='regular';$labels=['bill'=>'Bill','tax_invoice'=>'Tax invoice','bill_of_supply'=>'Bill of supply','credit_note'=>'Credit note'];$address=$buyer['delivery_address']??[];$logo=image_url($seller['logo_url']??'');if(($seller['logo_url']??'')==='/static/branding/annam-bill-logo.png')$logo='/media/brand/annam-bill-logo.png'; ?>
<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="robots" content="noindex,nofollow"><title><?= e($invoice['number']) ?> · <?= e($seller['name']) ?></title><link rel="stylesheet" href="/assets/receipt.css"></head><body><article class="af-receipt"><header class="af-receipt-head"><?php if($logo): ?><img class="af-receipt-logo" src="<?= e($logo) ?>" alt="<?= e($seller['name']) ?> logo"><?php endif; ?><h2><?= e($seller['name']) ?></h2><p class="af-receipt-tagline"><?= e($seller['tagline']??'') ?></p><?php if($invoice['kind']!=='bill'): ?><h3 class="af-document-title"><?= e($labels[$invoice['kind']]??'Bill') ?></h3><?php endif; ?><span class="af-receipt-badge"><?= $credit?'Credit note issued':'✓ Payment received' ?></span></header>
<dl class="af-receipt-meta"><?php foreach(['Bill number'=>$invoice['number'],'Issued'=>date('j M Y, g:i A',strtotime($invoice['issued_at'])),'Order / meal'=>($buyer['order_no']??'').' · '.($buyer['slot']??'')] as $label=>$value): ?><div><dt><?= e($label) ?></dt><dd><?= e($value) ?></dd></div><?php endforeach; ?></dl>
<section class="af-receipt-customer"><h3>Customer & delivery</h3><p class="af-customer-name"><?= e($buyer['name']??'') ?></p><p><?= e($buyer['phone']??'') ?></p><?php foreach(['business_name','billing_address','gstin'] as $key): if(!empty($buyer[$key])): ?><p><?= nl2br(e($buyer[$key])) ?></p><?php endif; endforeach; ?><p class="af-delivery-address"><?= e(($address['fulfilment']??'')==='Collection'?'Collection':implode(', ',array_unique(array_filter(array_map(fn($key)=>$address[$key]??'', ['line1','line2','landmark','area','city','pincode']))))) ?></p><?php if($buyer['delivery_date']??''): ?><p>Delivery: <?= e($buyer['delivery_date']) ?></p><?php endif; ?></section>
<table class="af-receipt-items"><thead><tr><th><?= $credit?'Credited items':'Your order' ?></th><th>Amount</th></tr></thead><tbody><?php foreach($invoice['lines'] as $line): ?><tr><td><strong><?= e($line['description']) ?></strong><span class="af-item-detail"><?= e($line['quantity']) ?> × <?= money((string)$line['unit_price']) ?><span class="af-item-sac"> · SAC / HSN: <?= e($line['sac']??'') ?></span></span><?php if($taxRegistered): ?><span class="af-item-detail">Taxable: <?= money((string)$line['taxable']) ?> · GST <?= e($line['tax_rate']) ?>%: <?= money((string)$line['tax']) ?></span><?php endif; ?></td><td><?= Money::display(Money::parse((string)$line['taxable'])+Money::parse((string)$line['tax'])) ?></td></tr><?php endforeach; ?></tbody></table>
<dl class="af-receipt-summary"><div><dt><?= $taxRegistered?'Taxable value':'Subtotal' ?></dt><dd><?= money($invoice['taxable']) ?></dd></div><?php if($taxRegistered): foreach(['cgst','sgst','igst'] as $key): ?><div><dt><?= e(strtoupper($key)) ?></dt><dd><?= money($invoice[$key]) ?></dd></div><?php endforeach; endif; ?><div><dt>Round off</dt><dd>₹<?= e($invoice['round_off']) ?></dd></div></dl><div class="af-receipt-total"><span><?= $credit?'Credit total':'Total paid' ?></span><strong><?= money($invoice['total']) ?></strong></div><p class="af-receipt-words"><?= e($invoice['amount_words']) ?></p><div class="af-receipt-payment"><p>Payment: <?= e($invoice['payment_mode']) ?></p><p><?= $credit?'Reason':'Reference' ?>: <?= e($invoice['payment_ref']) ?></p></div>
<?php if(($seller['gst_mode']??'')==='composition'): ?><p class="af-receipt-notice">Composition taxable person, not eligible to collect tax on supplies.</p><?php endif; ?><footer class="af-receipt-footer"><h3>Thank you for ordering with us!</h3><p><?= nl2br(e($seller['footer']??'')) ?></p><p class="af-receipt-signature">Authorised signatory</p><div class="af-receipt-legal"><p><strong><?= e($seller['name']) ?></strong> · <?= nl2br(e($seller['address'])) ?></p><p><?= e($seller['state'].' · State code '.$seller['state_code']) ?><br>FSSAI: <?= e($seller['fssai_no']) ?><?php if($seller['gstin']): ?><br>GSTIN: <?= e($seller['gstin']) ?><?php endif; ?></p></div></footer></article><div class="bill-actions"><button id="print-bill">Print / Save PDF</button><a href="javascript:history.back()">Back</a></div><script src="/assets/print.js" defer></script></body></html>
